[ "$A" = arm64 ] || [ -f images/ghcr.io-hatchet-dev-hatchet-hatchet-migrate-v0.120.5-amd64.docker.tar ] || "$F" ghcr.io/hatchet-dev/hatchet/hatchet-migrate sha256:fe2164ca4173d719a106157977c23d8c5bcd9ca73b1e476754164b14d1f12021 ghcr.io/hatchet-dev/hatchet/hatchet-migrate:v0.120.5 images/ghcr.io-hatchet-dev-hatchet-hatchet-migrate-v0.120.5-amd64.docker.tar
[ "$A" = x86_64 ] || [ -e images/ghcr.io-hatchet-dev-hatchet-hatchet-admin-v0.120.5-arm64-oci ] || "$F" ghcr.io/hatchet-dev/hatchet/hatchet-admin sha256:5e164c9be196098e807b313bec0ba10cefc4752ec4633b43502da953706d038e ghcr.io/hatchet-dev/hatchet/hatchet-admin:v0.120.5 images/ghcr.io-hatchet-dev-hatchet-hatchet-admin-v0.120.5-arm64-oci
[ "$A" = arm64 ] || [ -f images/ghcr.io-hatchet-dev-hatchet-hatchet-admin-v0.120.5-amd64.docker.tar ] || "$F" ghcr.io/hatchet-dev/hatchet/hatchet-admin sha256:5e36a86a44860774ba419a985fea25bccc0b1b964abfa0a3acbdcabb892175ab ghcr.io/hatchet-dev/hatchet/hatchet-admin:v0.120.5 images/ghcr.io-hatchet-dev-hatchet-hatchet-admin-v0.120.5-amd64.docker.tar
[ "$A" = x86_64 ] || [ -e images/ghcr.io-hatchet-dev-hatchet-hatchet-engine-v0.120.5-arm64-oci ] || "$F" ghcr.io/hatchet-dev/hatchet/hatchet-engine sha256:1c7e3696dbc93a5e76915fdf9b0b30b2fd7f1a5254a75a5dc43db5c66b7b26e5 ghcr.io/hatchet-dev/hatchet/hatchet-engine:v0.120.5 images/ghcr.io-hatchet-dev-hatchet-hatchet-engine-v0.120.5-arm64-oci
[ "$A" = arm64 ] || [ -f images/ghcr.io-hatchet-dev-hatchet-hatchet-engine-v0.120.5-amd64.docker.tar ] || "$F" ghcr.io/hatchet-dev/hatchet/hatchet-engine sha256:1c5e6e5bd18aba462af3f31ccf589946111abfbe7a4240afc8e13892637668e1 ghcr.io/hatchet-dev/hatchet/hatchet-engine:v0.120.5 images/ghcr.io-hatchet-dev-hatchet-hatchet-engine-v0.120.5-amd64.docker.tar
